from pathlib import Path

path = Path('RingContainer.js')
text = path.read_text()

text = text.replace('''    #inset;\n    #width;\n''', '''    #inset;\n    #width;\n    #margin;\n    #innerMargin;\n    #outerMargin;\n\n    #sizeObserver;\n''', 1)

text = text.replace('''        this.#width =\n            this.getAttribute(\n                "width"\n            );\n\n        this.#shadowRoot =''', '''        this.#width =\n            this.getAttribute(\n                "width"\n            );\n\n        this.#margin =\n            this.getAttribute(\n                "margin"\n            );\n\n        this.#innerMargin =\n            this.getAttribute(\n                "inner-margin"\n            );\n\n        this.#outerMargin =\n            this.getAttribute(\n                "outer-margin"\n            );\n\n        this.#shadowRoot =''', 1)

text = text.replace('''        this.#shadowRoot.appendChild(\n            this.#container\n        );\n\n        this.#updateStyle();''', '''        this.#shadowRoot.appendChild(\n            this.#container\n        );\n\n        this.#refreshNormalizedLengthAttributes();\n\n        this.#updateStyle();''', 1)

text = text.replace('''        this.#updateDuration();\n\n        RingContainer.#recalculateParent(''', '''        this.#updateDuration();\n\n        this.#startSizeObserver();\n\n        RingContainer.#recalculateParent(''', 1)

text = text.replace('''        const parent =\n            this.#parent;\n\n        this.#cancelAnimation();''', '''        const parent =\n            this.#parent;\n\n        this.#stopSizeObserver();\n\n        this.#cancelAnimation();''', 1)

marker = '''    get renderedInset() {\n'''
public_setters = '''    get inset() {\n        return this.#inset;\n    }\n\n    set inset(value) {\n        this.#setLengthValue(\n            "inset",\n            value\n        );\n    }\n\n    get width() {\n        return this.#width;\n    }\n\n    set width(value) {\n        this.#setLengthValue(\n            "width",\n            value\n        );\n    }\n\n    get margin() {\n        return this.#margin;\n    }\n\n    set margin(value) {\n        this.#setLengthValue(\n            "margin",\n            value\n        );\n    }\n\n    get innerMargin() {\n        return this.#innerMargin;\n    }\n\n    set innerMargin(value) {\n        this.#setLengthValue(\n            "inner-margin",\n            value\n        );\n    }\n\n    get outerMargin() {\n        return this.#outerMargin;\n    }\n\n    set outerMargin(value) {\n        this.#setLengthValue(\n            "outer-margin",\n            value\n        );\n    }\n\n'''
if public_setters not in text:
    text = text.replace(marker, public_setters + marker, 1)

old_callback = '''        if (\n            name === "inset"\n        ) {\n            this.#inset =\n                newValue;\n        }\n\n        if (\n            name === "width"\n        ) {\n            this.#width =\n                newValue;\n        }\n\n        if (\n            name === "margin" ||\n            name === "inner-margin" ||\n            name === "outer-margin"\n        ) {\n            this.#handleMarginAttributeChange(\n                name,\n                newValue\n            );\n        }\n\n        if (\n            !this.isConnected\n        ) {\n            this.#cancelAnimation();\n\n            this.#resizePending =\n                false;\n\n            this.#reorderPending =\n                false;\n\n            this.#pendingLifecycleAction =\n                undefined;\n\n            this.#updateProperties(\n                false\n            );\n\n            return;\n        }\n\n        if (\n            this.#parentHasPendingReorder()\n        ) {\n            this.#markParentRingsPending();\n\n            if (\n                !RingContainer.#batchResizing\n            ) {\n                RingContainer.#flushResizeBatch();\n            }\n\n            return;\n        }\n\n        this.#scheduleResize();\n\n        this.#updateAutomaticFollowingRings(\n            true\n        );'''
new_callback = '''        switch (name) {\n            case "inset":\n                this.inset = newValue;\n                break;\n\n            case "width":\n                this.width = newValue;\n                break;\n\n            case "margin":\n                this.margin = newValue;\n                break;\n\n            case "inner-margin":\n                this.innerMargin = newValue;\n                break;\n\n            case "outer-margin":\n                this.outerMargin = newValue;\n                break;\n        }'''
if old_callback not in text:
    raise SystemExit('attribute callback target not found')
text = text.replace(old_callback, new_callback, 1)

start = text.index('    #handleMarginAttributeChange(')
end = text.index('    #updateProperties(', start)
replacement = '''    #setLengthValue(\n        name,\n        value\n    ) {\n        const allowAuto =\n            name === "inset";\n\n        let original;\n\n        if (\n            value !== null &&\n            value !== undefined\n        ) {\n            original =\n                String(value).trim();\n\n            if (\n                allowAuto &&\n                original.toLowerCase() ===\n                    "auto"\n            ) {\n                original = "auto";\n            }\n            else if (\n                !RingContainer.#isValidLength(\n                    original\n                )\n            ) {\n                original = "0px";\n            }\n        }\n\n        switch (name) {\n            case "inset":\n                this.#inset = original;\n                break;\n\n            case "width":\n                this.#width = original;\n                break;\n\n            case "margin":\n                this.#margin = original;\n                break;\n\n            case "inner-margin":\n                this.#innerMargin = original;\n                break;\n\n            case "outer-margin":\n                this.#outerMargin = original;\n                break;\n        }\n\n        this.#syncingAttribute =\n            true;\n\n        try {\n            if (\n                original === undefined\n            ) {\n                this.removeAttribute(\n                    name\n                );\n            }\n            else if (\n                allowAuto &&\n                original === "auto"\n            ) {\n                this.setAttribute(\n                    name,\n                    "auto"\n                );\n            }\n            else {\n                this.setAttribute(\n                    name,\n                    this.#normalizeLengthToPixels(\n                        original\n                    )\n                );\n            }\n\n            if (\n                name === "margin" &&\n                original !== undefined\n            ) {\n                this.#innerMargin =\n                    undefined;\n\n                this.#outerMargin =\n                    undefined;\n\n                this.removeAttribute(\n                    "inner-margin"\n                );\n\n                this.removeAttribute(\n                    "outer-margin"\n                );\n            }\n        }\n        finally {\n            this.#syncingAttribute =\n                false;\n        }\n\n        this.#afterLengthValueChange();\n    }\n\n    #afterLengthValueChange() {\n        if (\n            !this.isConnected\n        ) {\n            this.#cancelAnimation();\n\n            this.#resizePending =\n                false;\n\n            this.#reorderPending =\n                false;\n\n            this.#pendingLifecycleAction =\n                undefined;\n\n            this.#updateProperties(\n                false\n            );\n\n            return;\n        }\n\n        if (\n            this.#parentHasPendingReorder()\n        ) {\n            this.#markParentRingsPending();\n\n            if (\n                !RingContainer.#batchResizing\n            ) {\n                RingContainer.#flushResizeBatch();\n            }\n\n            return;\n        }\n\n        this.#scheduleResize();\n\n        this.#updateAutomaticFollowingRings(\n            true\n        );\n    }\n\n    #normalizeLengthToPixels(\n        value\n    ) {\n        const measure =\n            document.createElement(\n                "div"\n            );\n\n        measure.style.position =\n            "absolute";\n\n        measure.style.visibility =\n            "hidden";\n\n        measure.style.pointerEvents =\n            "none";\n\n        measure.style.marginLeft =\n            value;\n\n        this.#shadowRoot.appendChild(\n            measure\n        );\n\n        const resolved =\n            Number.parseFloat(\n                getComputedStyle(\n                    measure\n                ).marginLeft\n            );\n\n        measure.remove();\n\n        const pixels =\n            Number.isFinite(resolved)\n                ? resolved\n                : 0;\n\n        return `${pixels}px`;\n    }\n\n    #refreshNormalizedLengthAttributes() {\n        this.#syncingAttribute =\n            true;\n\n        try {\n            const values = [\n                ["inset", this.#inset],\n                ["width", this.#width],\n                ["margin", this.#margin],\n                ["inner-margin", this.#innerMargin],\n                ["outer-margin", this.#outerMargin]\n            ];\n\n            for (\n                const [name, original] of\n                    values\n            ) {\n                if (\n                    original === null ||\n                    original === undefined\n                ) {\n                    continue;\n                }\n\n                if (\n                    name === "inset" &&\n                    original === "auto"\n                ) {\n                    if (\n                        this.getAttribute(name) !==\n                            "auto"\n                    ) {\n                        this.setAttribute(\n                            name,\n                            "auto"\n                        );\n                    }\n\n                    continue;\n                }\n\n                const normalized =\n                    this.#normalizeLengthToPixels(\n                        original\n                    );\n\n                if (\n                    this.getAttribute(name) !==\n                        normalized\n                ) {\n                    this.setAttribute(\n                        name,\n                        normalized\n                    );\n                }\n            }\n        }\n        finally {\n            this.#syncingAttribute =\n                false;\n        }\n    }\n\n    #startSizeObserver() {\n        if (\n            this.#sizeObserver ||\n            typeof ResizeObserver ===\n                "undefined"\n        ) {\n            return;\n        }\n\n        this.#sizeObserver =\n            new ResizeObserver(\n                () => {\n                    this.#refreshNormalizedLengthAttributes();\n\n                    this.#updateProperties(\n                        false\n                    );\n\n                    this.#updateAutomaticFollowingRings(\n                        false\n                    );\n\n                    this.#refreshChildVisualGeometry();\n                }\n            );\n\n        this.#sizeObserver.observe(\n            this\n        );\n    }\n\n    #stopSizeObserver() {\n        if (\n            !this.#sizeObserver\n        ) {\n            return;\n        }\n\n        this.#sizeObserver.disconnect();\n\n        this.#sizeObserver =\n            undefined;\n    }\n\n'''
text = text[:start] + replacement + text[end:]

text = text.replace('''    #usesAutomaticInset() {\n        if (\n            !this.hasAttribute(\n                "inset"\n            )\n        ) {\n            return true;\n        }\n\n        return (\n            this.getAttribute(\n                "inset"\n            )\n                ?.trim()\n                .toLowerCase() ===\n            "auto"\n        );\n    }''', '''    #usesAutomaticInset() {\n        return (\n            this.#inset === null ||\n            this.#inset === undefined ||\n            this.#inset\n                .trim()\n                .toLowerCase() ===\n                "auto"\n        );\n    }''', 1)

text = text.replace('''    #getInnerMargin() {\n        if (\n            this.hasAttribute(\n                "inner-margin"\n            )\n        ) {\n            return (\n                this.getAttribute(\n                    "inner-margin"\n                ) ??\n                "0px"\n            );\n        }\n\n        return (\n            this.getAttribute(\n                "margin"\n            ) ??\n            "0px"\n        );\n    }\n\n    #getOuterMargin() {\n        if (\n            this.hasAttribute(\n                "outer-margin"\n            )\n        ) {\n            return (\n                this.getAttribute(\n                    "outer-margin"\n                ) ??\n                "0px"\n            );\n        }\n\n        return (\n            this.getAttribute(\n                "margin"\n            ) ??\n            "0px"\n        );\n    }''', '''    #getInnerMargin() {\n        if (\n            this.#innerMargin !==\n                null &&\n            this.#innerMargin !==\n                undefined\n        ) {\n            return this.#innerMargin;\n        }\n\n        return (\n            this.#margin ??\n            "0px"\n        );\n    }\n\n    #getOuterMargin() {\n        if (\n            this.#outerMargin !==\n                null &&\n            this.#outerMargin !==\n                undefined\n        ) {\n            return this.#outerMargin;\n        }\n\n        return (\n            this.#margin ??\n            "0px"\n        );\n    }''', 1)

path.write_text(text)
